#include <bits/stdc++.h>
using namespace std;

// LeetCode SQL problems are not solvable in C++ via class Solution;
// equivalent logic shown as a standalone function.
vector<string> findInvestments(
    vector<tuple<int, string, string>>& person,
    vector<tuple<string, string>>& country,
    vector<tuple<int, int, int>>& calls) {
    unordered_map<int, string> codeOf;
    for (auto& [id, nm, ph] : person) codeOf[id] = ph.substr(0, 3);
    unordered_map<string, string> nameOf;
    for (auto& [nm, code] : country) nameOf[code] = nm;
    unordered_map<string, pair<long long, long long>> agg;
    long long totalSum = 0, totalCnt = 0;
    for (auto& [caller, callee, dur] : calls) {
        string cs[2] = {codeOf[caller], codeOf[callee]};
        for (string& c : cs) {
            agg[c].first += dur;
            agg[c].second++;
        }
        totalSum += 2LL * dur;
        totalCnt += 2;
    }
    vector<string> res;
    double globalAvg = (double)totalSum / totalCnt;
    for (auto& [code, sc] : agg)
        if ((double)sc.first / sc.second > globalAvg)
            res.push_back(nameOf[code]);
    return res;
}

