import java.util.*;

class Solution {
    public List<String> findInvestments(int[] ids, String[] phones,
                                        String[] countryNames, String[] countryCodes,
                                        int[] callers, int[] callees, int[] durations) {
        Map<Integer, String> codeOf = new HashMap<>();
        for (int i = 0; i < ids.length; i++) codeOf.put(ids[i], phones[i].substring(0, 3));
        Map<String, String> nameOf = new HashMap<>();
        for (int i = 0; i < countryCodes.length; i++) nameOf.put(countryCodes[i], countryNames[i]);
        Map<String, long[]> agg = new HashMap<>();
        long totalSum = 0, totalCnt = 0;
        for (int i = 0; i < durations.length; i++) {
            String[] codes = {codeOf.get(callers[i]), codeOf.get(callees[i])};
            for (String c : codes) {
                long[] a = agg.computeIfAbsent(c, k -> new long[2]);
                a[0] += durations[i];
                a[1]++;
            }
            totalSum += 2L * durations[i];
            totalCnt += 2;
        }
        List<String> res = new ArrayList<>();
        double globalAvg = (double) totalSum / totalCnt;
        for (Map.Entry<String, long[]> e : agg.entrySet())
            if ((double) e.getValue()[0] / e.getValue()[1] > globalAvg)
                res.add(nameOf.get(e.getKey()));
        return res;
    }
}

