/**
 * @param {number[]} ids
 * @param {string[]} phones
 * @param {string[]} countryNames
 * @param {string[]} countryCodes
 * @param {number[]} callers
 * @param {number[]} callees
 * @param {number[]} durations
 */
var findInvestments = function(ids, phones, countryNames, countryCodes, callers, callees, durations) {
    const codeOf = new Map();
    ids.forEach((id, i) => codeOf.set(id, phones[i].slice(0, 3)));
    const nameOf = new Map();
    countryCodes.forEach((c, i) => nameOf.set(c, countryNames[i]));
    const agg = new Map();
    let totalSum = 0, totalCnt = 0;
    for (let i = 0; i < durations.length; i++) {
        for (const id of [callers[i], callees[i]]) {
            const code = codeOf.get(id);
            const a = agg.get(code) || [0, 0];
            a[0] += durations[i];
            a[1]++;
            agg.set(code, a);
        }
        totalSum += 2 * durations[i];
        totalCnt += 2;
    }
    const res = [];
    const globalAvg = totalSum / totalCnt;
    for (const [code, sc] of agg)
        if (sc[0] / sc[1] > globalAvg) res.push(nameOf.get(code));
    return res;
};

